1	import '../../domain/entities/entry.dart';
2	import '../../domain/entities/entry_date_group.dart';
3	
4	/// `MeusRegistrosScreen`'s own sealed state — never the shared
5	/// `Resource<T>` (Boundaries, mirrors `capture`'s `TextEntryState`
6	/// sealed-class convention, `resource.dart`'s own doc already excludes
7	/// RF07 the same way): this screen's shape — a first load, a grouped list
8	/// with its own pagination sub-state, an empty result, or a terminal
9	/// error — doesn't fit that single-fetch lifecycle.
10	sealed class MeusRegistrosState {
11	  const MeusRegistrosState();
12	}
13	
14	/// The first page is in flight — `MeusRegistrosScreen` shows a skeleton
15	/// for this only past the shared 300ms threshold (RNF01), mirroring
16	/// `BootSplashScreen`'s own `Timer` pattern; blank below it.
17	class MeusRegistrosLoading extends MeusRegistrosState {
18	  const MeusRegistrosLoading();
19	}
20	
21	/// The first page resolved with zero entries (Boundaries: "Zero entries ->
22	/// Plain 'no entries yet' text", no polished CTA — that's story 4.3).
23	class MeusRegistrosEmpty extends MeusRegistrosState {
24	  const MeusRegistrosEmpty();
25	}
26	
27	/// The first load failed with a `Failure` the repository's own
28	/// offline/Hive fallback never absorbs (e.g. `Failure.authExpired`) —
29	/// [message] is `Failure.message` verbatim, same convention
30	/// `TextEntryError.message` already uses.
31	class MeusRegistrosError extends MeusRegistrosState {
32	  const MeusRegistrosError({required this.message});
33	
34	  final String message;
35	
36	  @override
37	  bool operator ==(Object other) =>
38	      identical(this, other) ||
39	      (other is MeusRegistrosError && other.message == message);
40	
41	  @override
42	  int get hashCode => message.hashCode;
43	
44	  @override
45	  String toString() => 'MeusRegistrosError(message: $message)';
46	}
47	
48	/// A resolved page — [entries] accumulates every page fetched so far
49	/// (first load plus every successful [MeusRegistrosCubit.loadMore]),
50	/// already de-duplicated by id. [groups] re-derives the grouped view via
51	/// the pure `groupEntriesByDate()` on every read rather than this state
52	/// storing a separately-maintained, pre-grouped copy that `loadMore` would
53	/// otherwise have to keep in sync by hand.
54	class MeusRegistrosLoaded extends MeusRegistrosState {
55	  const MeusRegistrosLoaded({
56	    required this.entries,
57	    required this.nextCursor,
58	    this.isLoadingMore = false,
59	    this.loadMoreFailed = false,
60	  });
61	
62	  final List<Entry> entries;
63	
64	  /// `null` once the server's `meta.nextCursor` says there's no further
65	  /// page — also always `null` for a page served from the offline Hive
66	  /// fallback (Boundaries).
67	  final String? nextCursor;
68	
69	  /// `true` for the duration of one in-flight `loadMore()` call —
70	  /// `MeusRegistrosScreen`'s list footer shows a small spinner for this,
71	  /// distinct from the first load's full-screen skeleton.
72	  final bool isLoadingMore;
73	
74	  /// `true` after a `loadMore()` attempt fails — I/O matrix: "keeps
75	  /// current items + inline retry". [entries] is left exactly as it was;
76	  /// only the footer switches to a retry affordance.
77	  final bool loadMoreFailed;
78	
79	  List<EntryDateGroup> get groups => groupEntriesByDate(entries);
80	
81	  MeusRegistrosLoaded copyWith({
82	    List<Entry>? entries,
